const b = ($json.body && typeof $json.body === 'object') ? $json.body : {};

const types = {
  bug:   { etiquette: 'bug',             defaut_titre: '[BUG] ' },
  us:    { etiquette: 'user-story',      defaut_titre: '[US] '  },
  tache: { etiquette: 'tache-technique', defaut_titre: '[TACHE] ' },
};

const t = types[String(b.type || '').toLowerCase()];
if (!t) {
  return [];
}
if (!b.titre || !String(b.titre).trim()) {
  return [];
}

const corps = String(b.corps || '').trim() ||
  '_Ticket cree sans description. Completer avant de poser agent:go._';

return [{ json: {
  etiquette_type: t.etiquette,
  titre: t.defaut_titre + String(b.titre).trim(),
  corps,
  avec_agent_go: b.demarrer !== false
} }];

const t = $input.first().json;
const etiquettes = (t.labels || []).map(l => l.name).join(', ');

return [{ json: {
  numero: t.number,
  lien: t.html_url,
  titre: t.title,
  etiquettes,
  chaine_lancee: etiquettes.includes('agent:go'),
  message: `Ticket #${t.number} cree — ${t.title}\nEtiquettes : ${etiquettes}\nLien : ${t.html_url}`,
  horodatage: new Date().toLocaleString('fr-FR')
} }];
